"use client";

import React, { useEffect, useState } from "react";
import { ResponsiveContainer, AreaChart, Area, XAxis, YAxis, Tooltip } from "recharts";
import { api } from "@/lib/api";
import { useCurrentUser } from "@/lib/use-current-user";
import type { Metric, Lead } from "@/types";

const chartData = [
  { name: "14d", value: 23 },
  { name: "13d", value: 25 },
  { name: "12d", value: 22 },
  { name: "11d", value: 28 },
  { name: "10d", value: 32 },
  { name: "9d", value: 30 },
  { name: "8d", value: 35 },
  { name: "7d", value: 38 },
  { name: "6d", value: 36 },
  { name: "5d", value: 42 },
  { name: "4d", value: 45 },
  { name: "3d", value: 43 },
  { name: "2d", value: 48 },
  { name: "Today", value: 51 },
];

function MetricCard({ metric }: { metric: Metric }) {
  return (
    <div className="bg-dark-card rounded-lg p-5">
      <div className="flex items-center justify-between">
        <p className="text-sm text-dark-text-secondary">{metric.title}</p>
        {metric.change ? (
          <span
            className={`text-sm font-semibold ${
              metric.change.startsWith("↑") ? "text-green-400" : "text-red-400"
            }`}
          >
            {metric.change}
          </span>
        ) : null}
      </div>
      <p className="text-4xl font-semibold mt-2">{metric.value}</p>
      <p className="text-sm text-dark-text-secondary mt-1">{metric.subtitle}</p>
    </div>
  );
}

export default function DashboardPage() {
  const user = useCurrentUser();
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const run = async () => {
      if (!user) {
        setLoading(false);
        return;
      }
      const leads: Lead[] = await api.getLeads(user.tenantId);
      const totalValue = leads.reduce((acc, lead) => acc + lead.value, 0);
      const formatted = new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: "USD",
        minimumFractionDigits: 0,
      }).format(totalValue);

      const contacted = leads.filter((l) =>
        ["Contacted", "Booked", "Closed"].includes(l.status)
      ).length;
      const booked = leads.filter((l) => l.status === "Booked").length;
      const winRate =
        contacted > 0 ? `${Math.round((booked / contacted) * 100)}% win rate` : "0% win rate";

      setMetrics([
        { title: "Leads", value: leads.length.toString(), subtitle: "Last 14 days" },
        { title: "Conversations", value: "742", change: "↑ 12%", subtitle: "vs previous 14d" },
        { title: "Bookings", value: booked.toString(), change: winRate, subtitle: "From contacted" },
        { title: "Revenue Impact", value: formatted, subtitle: "Est. client value" },
      ]);
      setLoading(false);
    };
    run();
  }, [user]);

  if (loading) return <div>Loading...</div>;

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {metrics.map((m) => (
          <MetricCard key={m.title} metric={m} />
        ))}
      </div>
      <div className="bg-dark-card rounded-lg p-6">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-semibold">Performance</h3>
          <span className="text-sm text-dark-text-secondary">Last 14 days</span>
        </div>
        <div className="h-80">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData} margin={{ top: 5, right: 20, left: -20, bottom: 5 }}>
              <defs>
                <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#6366f1" stopOpacity={0.4} />
                  <stop offset="95%" stopColor="#6366f1" stopOpacity={0} />
                </linearGradient>
              </defs>
              <Tooltip
                contentStyle={{
                  backgroundColor: "#0f172a",
                  border: "none",
                  borderRadius: "0.5rem",
                }}
                cursor={{ stroke: "#6366f1", strokeWidth: 1, strokeDasharray: "3 3" }}
              />
              <XAxis dataKey="name" stroke="#475569" fontSize={12} tickLine={false} axisLine={false} />
              <YAxis stroke="#475569" fontSize={12} tickLine={false} axisLine={false} />
              <Area type="monotone" dataKey="value" stroke="#6366f1" strokeWidth={2} fill="url(#chartGradient)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}
